function coP(){if(!S.set.cod&&CK.pm=="cod")CK.pm=null;const a=CK.addr,t=tot(CK.lines,CK.addr);return`<h1>Choose payment</h1><div class="two">${sumH()}<div class="pn">${t.g.some(x=>x.far)?`<div class="note">✅ Long-distance delivery approved by the shop owner. The approved delivery charge is included in your total.</div>`:""}<h2>Deliver to</h2><p class="sm">${esc(a.n)} · ${esc(a.m)}<br>${esc(a.a)}, ${esc(a.c)} ${esc(a.p)}</p><h2 style="margin:12px 0 8px">Payment method</h2>${S.set.cod?`<label class="po ${CK.pm=="cod"?"on":""}"><input type="radio" name="pm" ${CK.pm=="cod"?"checked":""} onchange="CK.pm='cod';go('co')">Cash on Delivery</label>`:`<p class="note">Cash on Delivery is not available right now. Please pay online by UPI.</p>`}<label class="po ${CK.pm=="upi"?"on":""}"><input type="radio" name="pm" ${CK.pm=="upi"?"checked":""} onchange="CK.pm='upi';go('co')">Pay Now (online payment)</label>${CK.pm=="cod"?`<p class="sm" style="margin-bottom:10px">You pay ${money(t.t)} in cash on delivery. Order status: Confirmed · Payment status: Pending.</p><button class="b" id="pb" style="width:100%" onclick="mk('cod')">Confirm COD Order</button>`:CK.pm=="upi"?`<p class="sm" style="margin-bottom:10px">Pay ${money(t.t)} online, then upload your payment proof to confirm the order.</p><button class="b" style="width:100%" onclick="CK.step=3;CK.pf=null;go('co')">Continue to Pay Now</button>`:`<p class="sm">Select a payment method.</p>`}<button class="o" style="width:100%;margin-top:8px" onclick="CK.step=1;go('co')">Back</button></div></div>`}
function upiV(){const t=tot(CK.lines,CK.addr);return`<h1>Pay Now</h1><p class="sm" style="margin:0 0 8px">Pay the exact amount using the scanner, then upload your payment proof. Your order is placed when you submit the proof. The store owner then checks your payment and confirms it.</p><div class="two"><div class="pn"><h2>Scan to pay</h2><div class="kp" style="margin:8px 0"><div><small>Exact amount</small><b>${money(t.t)}</b></div></div>${S.set.qr?`<img class="qri" src="${S.set.qr}" alt="Scan this QR code to pay"><p class="sm" style="text-align:center">Scan with any UPI app and pay the exact amount. Pay to: New Brahmani Beauty World.</p>`:`<div class="qr" role="img" aria-label="QR placeholder"></div><p class="sm" style="text-align:center">The store has not uploaded its payment scanner yet. Please try again later or choose Cash on Delivery if available.</p>`}</div><div class="pn"><h2 style="margin-bottom:10px">Payment proof</h2>${fld("up_r","UTR / reference (8–22 letters or digits)")}<div class="fg"><label for="up_i">Payment screenshot</label><input id="up_i" type="file" accept="image/*" onchange="upImg(this)"><div class="er" id="e_up_i"></div></div><div id="up_pv"></div><button class="b" id="upb" style="width:100%" onclick="upSub()">Submit payment proof &amp; place order</button><button class="o" style="width:100%;margin-top:8px" onclick="CK.step=2;go('co')">Back</button></div></div>`}
function readImg(f,mx){return new Promise((ok,no)=>{if(!f)return no(new Error("No file chosen"));const n=(f.name||"").toLowerCase();if(!(/^image\//.test(f.type)||/\.(jpe?g|png|webp|gif|bmp|heic|heif)$/.test(n)))return no(new Error("Please choose an image file (JPG, PNG or WebP)"));if(f.size>15e6)return no(new Error("Image is over 15 MB. Choose a smaller one"));const u=URL.createObjectURL(f),im=new Image;im.onload=()=>{const k=Math.min(1,(mx||1100)/Math.max(im.width,im.height)),c=document.createElement("canvas");c.width=Math.max(1,Math.round(im.width*k));c.height=Math.max(1,Math.round(im.height*k));const x=c.getContext("2d");x.fillStyle="#fff";x.fillRect(0,0,c.width,c.height);x.drawImage(im,0,0,c.width,c.height);URL.revokeObjectURL(u);ok(c.toDataURL("image/jpeg",.85))};im.onerror=()=>{URL.revokeObjectURL(u);no(new Error("This image could not be read. If it is a HEIC photo, choose a JPG or PNG instead"))};im.src=u})}
async function upImg(el){const f=el.files[0];CK.pf=null;$("e_up_i").textContent="";upPv();if(!f)return;try{CK.pf=await readImg(f);upPv()}catch(e){el.value="";$("e_up_i").textContent=e.message}}
const upPv=()=>{$("up_pv").innerHTML=CK.pf?`<div class="pvw"><div><img src="${CK.pf}" alt="Screenshot preview"><button aria-label="Remove screenshot" onclick="CK.pf=null;$('up_i').value='';upPv()">✕</button></div></div><p class="sm">Selected. Choose another file to replace it. Selecting an image does not verify any payment.</p>`:""};
async function upSub(){const r=$("up_r").value.trim();if(!/^[A-Za-z0-9]{8,22}$/.test(r)){$("e_up_r").textContent="Enter 8–22 letters or digits";return}$("e_up_r").textContent="";if(!CK.pf){$("e_up_i").textContent="Upload a screenshot (preview shown after selection)";return}if(S.o.some(o=>o.ref&&o.ref.toLowerCase()==r.toLowerCase())){$("e_up_r").textContent="This reference was already submitted";return}
const b=$("upb");b.disabled=1;b.textContent="Uploading…";
try{const u=await api("/uploads/proof",{method:"POST",body:{dataUrl:CK.pf}});await mk("upi",{ref:r,path:u.path})}catch(e){fail(e)}finally{const x=$("upb");if(x){x.disabled=0;x.textContent="Submit payment proof & place order"}}}
async function mk(pm,x){if(!ME||ME.role!="buyer")return toast("Only buyers can place orders");if(ME.blocked){go("cart");return toast(BLK_MSG)}if(pm!="cod"&&pm!="upi")return toast("Invalid payment method");if(pm=="cod"&&!S.set.cod){CK.pm=null;go("co");return toast("Cash on Delivery is currently unavailable. Please choose another method.")}
const t=tot(CK.lines,CK.addr);if(t.need){CK.step=5;go("co");return toast("Owner approval is required for deliveries above 10 km.")}
const pb=$("pb");if(pb)pb.disabled=1;
try{const r=await api("/orders",{method:"POST",body:{lines:CK.lines,addr:CK.addr,pm,ref:x&&x.ref,proof:x&&x.path,cart:!!CK.cart}});await sync();CK.os=r.orders.map(id=>S.o.find(o=>o.id==id)).filter(Boolean);if(CK.cart)CK.os.forEach(o=>o.items.forEach(i=>delete C[i.id]));cartN();bell();if(!CK.os.length){CK=null;go("orders");return toast("Order placed. See it under My Orders.")}CK.step=4;go("co")}
catch(e){if(e.status==409&&pm=="upi"&&$("e_up_r")&&/reference/i.test(e.message))$("e_up_r").textContent=e.message;fail(e);if(ME){try{await sync();bell();if(/no longer available|paused/i.test(e.message)){purge();cartN();go("cart")}}catch(z){}}}finally{if($("pb"))$("pb").disabled=0}}
function coD(){const os=CK.os,up=os[0].pm=="upi",T=sum(os,o=>o.tot);return`<div class="pn" style="text-align:center"><svg class="ck" viewBox="0 0 84 84"><circle cx="42" cy="42" r="38"/><path d="M26 43l11 11 21-23"/></svg><h1>${up?"Payment Proof Submitted":"Order Confirmed"}</h1><p>Order${os.length>1?"s":""} <b>${os.map(o=>o.id).join(", ")}</b> · ${money(T)}</p>${os.length>1?`<p class="sm">Your bag had items from ${os.length} stores, so it was split into ${os.length} orders.</p>`:""}<p class="sm" style="margin:8px 0 14px">${up?"Payment status: AWAITING VERIFICATION · The store owner will check your payment and confirm your order.":"Payment method: Cash on Delivery · Payment status: PENDING · Order status: CONFIRMED."}</p><div class="btns"><button class="b" onclick="CK=null;go('orders')">My Orders</button><button class="o" onclick="CK=null;go('shop')">Keep shopping</button></div></div>`}
