const pend=o=>o.pm=="cod"&&o.st=="Delivered"&&!o.recv,FLOW=["Confirmed","Packed","Shipped","Delivered"],dn=o=>o.st=="Delivered"||o.st=="Received by Buyer",fl=o=>o.pm=="upi"&&(o.hist||[]).includes("Awaiting Payment")?["Awaiting Payment",...FLOW]:[...FLOW,"Received by Buyer"];
VW.orders=()=>{const h=V.oh,l=S.o.filter(o=>o.by==ME.email&&(h?dn(o)&&!pend(o):!dn(o)||pend(o)));return`<h1>My Orders</h1>${drBuyer()}<div class="chips"><button class="${h?"":"on"}" onclick="V.oh=0;go('orders')">Active</button><button class="${h?"on":""}" onclick="V.oh=1;go('orders')">History</button></div>`+(l.map(o=>`<div class="pn"><b>${o.id}</b> ${pill(o.st)} <span class="sm">${fd(o.cr)} · ${esc(o.shop||"")}</span><br><span class="sm">${o.pm=="upi"?"Pay Now":"Cash on Delivery"} · Payment: ${esc(o.pay)}${o.km?" · ~"+o.km+" km"+(o.dm?" (estimated)":"")+(o.far?" · owner-approved delivery "+money(o.ddel):""):""}${o.cxr?" · Cancel reason: "+esc(o.cxr):""}</span>${o.items.map(i=>`<div class="ln"><div class="im">${i.img?`<img src="${i.img}" alt="">`:art(i.k,i.h)}</div><div class="n"><b>${esc(i.n)}</b><br><span class="sm">${i.q} × ${money(i.pr)}</span></div></div>`).join("")}${o.st=="Cancelled"?"":`<ul class="tl">${fl(o).map(s=>`<li class="${o.hist.includes(s)?"d":""}">${s}</li>`).join("")}</ul>`}<b>Total ${money(o.tot)}</b> ${["Awaiting Payment","Confirmed"].includes(o.st)?`<button class="o s" style="margin-left:8px" onclick="cancelAsk('${o.id}')">Cancel order</button>`:""}${o.pm=="cod"&&["Shipped","Delivered"].includes(o.st)&&!o.recv?`<button class="g s" style="margin-left:8px" onclick="cfmRecv('${o.id}')">I Have Taken Order</button>`:""}${o.pm=="cod"&&["Confirmed","Packed"].includes(o.st)?'<span class="sm" style="margin-left:8px">"I Have Taken Order" unlocks once your order is shipped.</span>':""}${dn(o)?`<button class="b s" style="margin-left:8px" onclick="again('${o.id}')">Buy again</button>`:""}</div>`).join("")||'<div class="pn empty">Nothing here yet.</div>')};

async function cancel(id,by,reason){if(!ME)return;if(by=="buyer"&&!reason)return toast("Please give a reason to cancel");try{await api("/orders/"+id+"/cancel",{method:"POST",body:{reason}});await sync();bell();toast("Order cancelled");go(V.v,"keep")}catch(e){fail(e);try{await sync();go(V.v,"keep")}catch(z){}}}
