const MU=["pcs","bottle","jar","tube","pack","box","set"],SZU=["ml","g","kg","L","pcs"],int1=x=>/^\d+$/.test(x)&&+x>0?"":"Whole number above 0",min2=x=>x.length>=2?"":"Enter at least 2 characters";
