function phist(id){const p=own(id);if(!p)return toast("Not allowed");opn(`<h2>${esc(p.n)}</h2><p class="sm">${p.id} · Original qty ${p.q0} · Available ${p.st} · ${SL(p)}</p><div style="margin:10px 0">${[...p.log].reverse().map(l=>`<div class="nt"><b>${esc(l.k)}</b>${l.d?` <span class="pill ${l.d>0?"ok":"x"}">${l.d>0?"+":""}${l.d}</span>`:""}<br>${esc(l.x)}<br><span class="sm">${fd(l.t)}</span></div>`).join("")}</div><button class="o" style="width:100%" onclick="cl()">Close</button>`)}
