VW.edit=()=>{const p=own(V.edit);if(!p)return VW.hist();const cb=p.t=="combo";return ownBar()+`<h1>Edit ${cb?"combo":"product"}</h1><div class="two"><div class="pn">${fld("e_n","Name",{v:p.n})}${cb?"":fld("e_b","Brand",{v:p.br})+fld("e_c","Category",{sel:CATS,v:p.c})}${fld("e_d","Description",{ta:1,v:p.d})}${cb?"":fld("e_u","How to use",{ta:1,v:p.us,opt:1})+fld("e_sz","Size / volume (e.g. 30 ml)",{v:p.sz,opt:1})+fld("e_va","Variant / shade",{v:p.va,opt:1})}${fimg("e_img","Replace images",4,1)}<p class="sm">Choosing new images replaces the current ones.</p></div><div class="pn">${fld("e_p","Unit price (₹)",{v:p.pr,im:"decimal"})}${cb?"":fld("e_dc","Discount % (0–90)",{v:p.dc||"",im:"numeric",opt:1})}${fld("e_s",cb?"Available packages":"Available quantity",{v:p.st,im:"numeric"})}${fld("e_r","Reason for quantity change",{opt:1})}${cb?"":fld("e_x","Expiry date",{t:"date",v:p.exp||"",opt:1})}${fld("e_l","Shelf / location",{v:p.loc||"Main store"})}${fld("e_a","Availability",{sel:["Active","Inactive"],v:p.on?"Active":"Inactive"})}<button class="b" id="e_b2" style="width:100%" onclick="saveE()">Save changes</button><button class="o" style="width:100%;margin-top:8px" onclick="go('hist')">Cancel</button></div></div>`};
function saveE(){const p=own(V.edit);if(!p)return toast("Not allowed");const cb=p.t=="combo",R=[["e_n",min2],["e_d",x=>x.length>=10?"":"Describe it (10+ characters)"],["e_p",num],["e_s",int0],["e_r",(x,v)=>+v.e_s!=p.st&&x.length<3?"Give a reason for the quantity change":""],["e_l",min2],["e_a",rq],["e_img",()=>""]];if(!cb)R.push(["e_b",rq],["e_c",rq],["e_dc",x=>!x||(/^\d+$/.test(x)&&+x<=90)?"":"0–90"],["e_x",x=>!x||x==p.exp||new Date(x)>new Date()?"":"Expiry date must be in the future"]);const v=chk(R);if(!v)return;
sub("e_b2",async()=>{const body={name:v.e_n,description:v.e_d,price:+v.e_p,stock:+v.e_s,reason:v.e_r||"",shelf:v.e_l,active:v.e_a=="Active"};if(!cb)Object.assign(body,{brand:v.e_b,category:v.e_c,discount:+v.e_dc||0,howToUse:$("e_u").value.trim(),size:$("e_sz").value.trim(),variant:$("e_va").value.trim(),expiry:v.e_x});if(IMG.e_img&&IMG.e_img.length)body.images=await upAll(IMG.e_img);const r=await api("/products/"+V.edit,{method:"PUT",body});await sync();bell();if(r.warning)toast(r.warning);if(!r.changes){if(!r.warning)toast("No changes to save");return}IMG={};toast("Product updated");go("hist")})}
