const osl=o=>o.st,fAddr=o=>o.addr?[o.addr.a,o.addr.c,o.addr.p].filter(Boolean).join(", "):"—";
const ordRow=o=>`<tr><td>${o.id}<br>${pill(osl(o))}</td><td>${esc(o.addr?o.addr.n:"Buyer")}<br><span class="sm">${esc(o.addr&&o.addr.m||"")}</span></td><td style="min-width:140px">${esc(fAddr(o))}${o.km?`<br><span class="sm">~${o.km} km${o.dm?" (estimated)":""}${o.far?" · owner-approved":""}</span>`:""}</td><td>${o.items.map(i=>`<div style="display:flex;gap:6px;align-items:center;margin-bottom:4px"><span style="width:34px;height:34px;border-radius:8px;border:1px solid var(--ln);overflow:hidden;flex:none;background:#fff">${i.img?`<img src="${i.img}" alt="" style="width:100%;height:100%;object-fit:cover">`:art(i.k,i.h)}</span>${esc(i.n)}</div>`).join("")}</td><td>${o.items.map(i=>i.q+" "+esc(i.u||"pcs")).join(", ")}</td><td>${o.items.map(i=>money(i.pr)).join(", ")}</td><td>${money(o.tot)}${o.del?`<br><span class="sm">incl. ${money(o.del)} delivery</span>`:""}</td><td>${fd(o.cr)}</td><td>${o.pm=="upi"?"Pay Now":"Cash on Delivery"}</td><td>${pill(o.pay)}</td><td class="sm">${o.cxr?"Cancel reason: "+esc(o.cxr)+"<br>":""}Delivered: ${o.done?fd(o.done):"—"}${o.ref?"<br>Ref: "+esc(o.ref):""}</td></tr>`;
VW.ord=()=>{const m=V.oc||"all",aw=owned().filter(o=>o.st=="Awaiting Payment"),L=owned().filter(o=>m=="all"||(m=="active"?!dn(o)&&o.st!="Cancelled":dn(o)||o.st=="Cancelled"));return ownBar()+`<h1>Orders</h1>${qrPanel()}${aw.length?`<div class="pn"><h2>Payments to verify</h2><p class="sm" style="margin-bottom:6px">Check your own UPI account before confirming. You verify payments yourself; no admin step.</p>${aw.map(o=>`<div class="ln"><div class="n"><b>${o.id}</b> · ${money(o.tot)}<br><span class="sm">Ref ${esc(o.ref||"—")} · ${fd(o.cr)}</span></div><button class="o s" onclick="vpf('${o.id}')">View proof</button><button class="g s" onclick="payOk('${o.id}')">Confirm</button><button class="d s" onclick="cancel('${o.id}','owner')">Reject</button></div>`).join("")}</div>`:""}<p class="sm" style="margin-bottom:8px">Buyers confirm collection and cash payment. Update order progress from the Today page.</p><div class="bar">${[["active","Active"],["done","Completed / history"],["all","All"]].map(([k,l])=>`<button class="${k==m?"b":"o"} s" onclick="V.oc='${k}';go('ord','keep')">${l}</button>`).join("")}</div>`+tb(["Order","Buyer","Delivery address","Product","Qty","Unit price","Amount","Placed","Method","Payment","Timestamps"],L.map(ordRow))};
async function vpf(id){const o=S.o.find(x=>x.id==id);if(!o||!isO()||o.oid!=ME.id)return toast("Not allowed");let url="";if(o.hasProof){try{url=(await api("/orders/"+id+"/proof")).url}catch(e){toast(e.message)}}
opn(`<h2>Payment proof</h2><p class="sm">${id} · ref ${esc(o.ref||"—")} · ${money(o.tot)}</p>${url?`<img src="${esc(url)}" alt="Payment screenshot" style="width:100%;border-radius:12px;margin:10px 0">`:'<p style="margin:10px 0">Screenshot not available.</p>'}<p class="sm">A screenshot alone is not proof of payment. Check your own account before confirming.</p><button class="o" style="width:100%;margin-top:10px" onclick="cl()">Close</button>`)}
async function payOk(id){const o=S.o.find(x=>x.id==id);if(!o||!isO()||o.oid!=ME.id)return toast("Not allowed");if(o.st!="Awaiting Payment")return;try{await api("/orders/"+id+"/confirm-payment",{method:"POST"});await sync();bell();toast("Payment confirmed");go("ord","keep")}catch(e){fail(e)}}
async function adv(id){const o=S.o.find(x=>x.id==id);if(!o||!isO()||o.oid!=ME.id)return toast("Not allowed");if(!FLOW.includes(o.st))return;try{const r=await api("/orders/"+id+"/advance",{method:"POST"});await sync();bell();toast(id+": "+r.status);go("today","keep")}catch(e){fail(e)}}
/* ---- Today ---- */
VW.today=()=>{const os=owned(),td=os.filter(o=>isT(o.cr)),d=os.filter(o=>dn(o)&&isT(o.done)),cx=os.filter(o=>o.st=="Cancelled"&&isT(o.cx)),m=mp(),g=sum(d,o=>o.tot),open=os.filter(o=>!dn(o)&&o.st!="Cancelled"),rows=[...new Map([...open,...td,...d].sort((a,b)=>b.cr-a.cr).map(o=>[o.id,o])).values()];
return ownBar()+`<h1>Today</h1><div class="kp"><div><small>Products added</small><b>${m.filter(p=>p.t=="single"&&isT(p.cr)).length}</b></div><div><small>Combos added</small><b>${m.filter(p=>p.t=="combo"&&isT(p.cr)).length}</b></div><div><small>Orders received</small><b>${td.length}</b></div><div><small>Products sold</small><b>${new Set(d.flatMap(o=>o.items.map(i=>i.id))).size}</b></div><div><small>Units sold</small><b>${sum(d,o=>sum(o.items,i=>i.q))}</b></div><div><small>Stock available</small><b>${sum(m.filter(p=>SL(p)=="Active"),p=>p.st)}</b></div><div><small>Deliveries completed</small><b>${d.length}</b></div><div><small>Cancelled</small><b>${cx.length}</b></div><div><small>Open orders</small><b>${open.length}</b></div><div><small>Gross sales</small><b>${money(g)}</b></div><div><small>Your net earnings</small><b>${money(g)}</b></div></div><p class="sm" style="margin-bottom:10px">Only delivered orders count as completed sales. There is no platform commission or admin settlement. Open orders from earlier days stay here until they are delivered or cancelled.</p>`+tb(["Order","Product","Qty","Buyer","Order status","Payment","Amount","Action"],rows.flatMap(o=>o.items.map((i,k)=>`<tr><td>${o.id}</td><td>${esc(i.n)}</td><td>${i.q} ${esc(i.u||"pcs")}</td><td>${esc(o.addr?o.addr.n:"Buyer")}</td><td>${pill(o.st)}</td><td>${esc(o.pay)}</td><td>${money(i.q*i.pr)}</td><td>${k?"":(FLOW.includes(o.st)&&o.st!="Delivered"?`<button class="g s" onclick="adv('${o.id}')">Mark ${FLOW[FLOW.indexOf(o.st)+1]}</button>`:o.st=="Awaiting Payment"?`<button class="o s" onclick="go('ord')">Verify payment</button>`:"")}</td></tr>`)))};
/* ---- Graph ---- */
const keyOf=(d,g)=>{d=new Date(d);if(g=="Week"){const x=sod(d);x.setDate(x.getDate()-(x.getDay()+6)%7);return"Wk "+x.toLocaleDateString("en-GB",{day:"2-digit",month:"short"})}if(g=="Month")return d.toLocaleDateString("en-GB",{month:"short",year:"2-digit"});return d.toLocaleDateString("en-GB",{day:"2-digit",month:"short"})};
const labs=(f,t,g)=>{const s=new Set;for(let d=sod(f);d<=t;d=new Date(+d+DAY))s.add(keyOf(d,g));return[...s]},agg=(L,g,rows,df,vf)=>{const m=Object.fromEntries(L.map(l=>[l,0]));rows.forEach(r=>{const d=df(r);if(d){const k=keyOf(d,g);if(k in m)m[k]+=vf(r)}});return L.map(l=>m[l])};
function bars(L,Sr,m){const W=680,H=190,pl=48,pb=26,n=L.length||1,mx=Math.max(4,...Sr.flatMap(s=>s.v)),gw=(W-pl)/n,bw=Math.max(3,gw*.7/Sr.length);let g="";for(let i=0;i<=4;i++){const y=H-pb-(H-pb-10)*i/4;g+=`<line x1="${pl}" x2="${W}" y1="${y}" y2="${y}" stroke="#E7D9DE"/><text x="${pl-6}" y="${y+4}" text-anchor="end" font-size="10" fill="#76657F">${m?"₹"+Math.round(mx*i/4):Math.round(mx*i/4)}</text>`}L.forEach((l,i)=>{Sr.forEach((s,k)=>{const h=(H-pb-10)*s.v[i]/mx,x=pl+i*gw+(gw-bw*Sr.length)/2+k*bw;g+=`<rect x="${x}" y="${H-pb-h}" width="${bw}" height="${h}" rx="3" fill="${s.c}"><title>${l} · ${s.n}: ${m?money(s.v[i]):s.v[i]}</title></rect>`});if(n<=12||i%Math.ceil(n/10)==0)g+=`<text x="${pl+i*gw+gw/2}" y="${H-8}" text-anchor="middle" font-size="10" fill="#76657F">${l}</text>`});return`<div class="tw"><svg viewBox="0 0 ${W} ${H}" style="width:100%;min-width:480px" role="img" aria-label="${esc(Sr.map(s=>s.n).join(" and "))} chart">${g}</svg></div><div class="sm" style="margin-top:4px">Total: ${Sr.map(s=>`<span style="color:${s.c}">■</span> ${s.n} ${m?money(sum(s.v,x=>x)):sum(s.v,x=>x)}`).join(" · ")}</div>`}
const rank=(a,m)=>{const mx=Math.max(1,...a.map(x=>x.v));return a.length?`<div class="rk">${a.map(x=>`<div><span title="${esc(x.n)}">${esc(x.n.slice(0,16))}</span><i style="width:${Math.max(2,x.v/mx*100)}%"></i><b>${m?money(x.v):x.v}</b></div>`).join("")}</div>`:'<div class="empty">No data in this period.</div>'};
const rng=()=>{const t=V.gt?new Date(V.gt+"T00:00:00"):sod(now()),f=V.gf?new Date(V.gf+"T00:00:00"):new Date(+t-29*DAY);return{f,t:new Date(+t+DAY-1),fs:f.toISOString().slice(0,10),ts:t.toISOString().slice(0,10)}};
const inR=(d,x)=>d&&d>=x.f&&d<=x.t,pStats=(orders,plist,x)=>plist.map(p=>{const s=orders.filter(o=>dn(o)&&inR(o.done,x)).flatMap(o=>o.items.filter(i=>i.id==p.id));return{n:p.n,v:sum(s,i=>i.q),r:sum(s,i=>i.q*i.pr),p}});
VW.graph=()=>{const x=rng(),g=V.gg||"Day",L=labs(x.f,x.t,g),os=owned(),D=os.filter(dn),m=mp().filter(p=>!p.del),ps=pStats(os,m,x),sorted=[...ps].sort((a,b)=>b.v-a.v),zero=ps.filter(s=>!s.v).length;
return ownBar()+`<h1>Graph</h1><div class="bar"><div class="fg"><label for="gf">From</label><input id="gf" type="date" value="${x.fs}" onchange="V.gf=this.value;go('graph','keep')"></div><div class="fg"><label for="gt">To</label><input id="gt" type="date" value="${x.ts}" onchange="V.gt=this.value;go('graph','keep')"></div><div class="fg"><label for="gg">Group by</label><select id="gg" onchange="V.gg=this.value;go('graph','keep')">${["Day","Week","Month"].map(c=>`<option ${c==g?"selected":""}>${c}</option>`).join("")}</select></div></div>
<div class="pn"><h3>Revenue trend (completed sales)</h3>${bars(L,[{n:"Revenue",c:"#2A0F3D",v:agg(L,g,D,o=>o.done,o=>o.tot)}],1)}</div><div class="pn"><h3>Quantity sold</h3>${bars(L,[{n:"Units",c:"#C9A96A",v:agg(L,g,D,o=>o.done,o=>sum(o.items,i=>i.q))}])}</div><div class="pn"><h3>Orders received vs completed</h3>${bars(L,[{n:"Received",c:"#B8607A",v:agg(L,g,os,o=>o.cr,()=>1)},{n:"Completed",c:"#2A0F3D",v:agg(L,g,D,o=>o.done,()=>1)}])}</div>
<div class="two"><div class="pn"><h3>Most-sold products</h3>${rank(sorted.filter(s=>s.v).slice(0,5))}</div><div class="pn"><h3>Least-sold products</h3>${rank([...ps].sort((a,b)=>a.v-b.v).slice(0,5))}<p class="sm" style="margin-top:6px">Lowest units sold in the selected dates. ${zero} of ${ps.length} listings had no sales; ties appear in listing order.</p></div><div class="pn"><h3>Top-performing combos</h3>${rank(sorted.filter(s=>s.p.t=="combo"&&s.v))}</div><div class="pn"><h3>Low-stock products</h3>${rank(m.filter(p=>SL(p)=="Active"&&p.st<=5).map(p=>({n:p.n,v:p.st})))}</div></div>`};
/* ---- owner: COD switch + Buyers management ---- */
const BLK_MSG="Your account is blocked from placing new orders. You can still view your past orders. Please contact the store owner for help.";
const blkB=()=>`<div class="errb"><b>Account restricted</b><br>${BLK_MSG}</div>`;

const codRow=()=>`<div class="note cod"><b>Cash on Delivery</b><span class="pill ${S.set.cod?"ok":"x"}">${S.set.cod?"ON":"OFF"}</span><span class="sm">${S.set.cod?"Buyers can choose COD at checkout.":"COD is hidden from buyers."}</span><button class="sw ${S.set.cod?"on":""}" role="switch" aria-checked="${S.set.cod?"true":"false"}" aria-label="Cash on Delivery" onclick="codT()"><i></i></button></div>`;
const qrPanel=()=>`<div class="pn"><h2>Online payment scanner (QR)</h2><p class="sm" style="margin-bottom:8px">Upload your UPI QR code. Buyers see this picture when they pay online.</p>${S.set.qr?`<img class="qri" src="${S.set.qr}" alt="Your payment scanner"><p style="text-align:center;margin-bottom:8px"><button class="d s" onclick="qrDel()">Remove scanner</button></p>`:`<p class="note">No scanner uploaded yet.</p>`}<div class="fg"><label for="qr_i">${S.set.qr?"Replace scanner picture":"Choose a file"}</label><input id="qr_i" type="file" accept="image/*" onchange="qrUp(this)"><div class="er" id="e_qr_i"></div></div></div>`;
async function qrUp(el){if(!isO())return toast("Not allowed");const e=$("e_qr_i");e.textContent="";try{const d=await readImg(el.files[0],700);await api("/uploads/qr",{method:"POST",body:{dataUrl:d}});await sync();toast("Scanner saved. Buyers will see it when paying online.");go("ord","keep")}catch(x){e.textContent=x.message;el.value=""}}
async function qrDel(){if(!isO())return;try{await api("/store/qr",{method:"DELETE"});await sync();toast("Scanner removed");go("ord","keep")}catch(e){fail(e)}}
async function codT(){if(!isO())return toast("Not allowed");try{const on=!S.set.cod;await api("/store/cod",{method:"POST",body:{on}});await sync();toast("Cash on Delivery turned "+(on?"ON":"OFF"));go(V.v,"keep")}catch(e){fail(e)}}
const BPG=8,bOrders=u=>owned().filter(o=>o.bid==u.id||o.by==u.email),bList=()=>S.u.filter(u=>u.role=="buyer");
const bAddrs=u=>{const a=[[u.a,u.c,u.p].filter(Boolean).join(", "),...bOrders(u).map(fAddr)].filter(x=>x&&x!="—");return[...new Set(a)]};
const bSpent=u=>sum(bOrders(u).filter(o=>o.st!="Cancelled"),o=>o.tot),bPill=u=>`<span class="pill ${u.blocked?"x":"ok"}">${u.blocked?"Blocked":"Active"}</span>`;
VW.buyers=()=>{if(!isO())return"";return ownBar()+`<h1>Buyers</h1><div class="bar"><div class="fg grow"><label for="bq">Search buyers</label><input id="bq" type="search" value="${esc(V.bq||"")}" placeholder="Name, email or mobile" oninput="const q=this.value;clearTimeout(V.bt);V.bt=setTimeout(()=>{V.bq=q;V.bp=0;drawB()},200)"></div></div><div class="chips">${[["all","All"],["act","Active"],["blk","Blocked"]].map(([k,l])=>`<button class="${(V.bs||"all")==k?"on":""}" onclick="V.bs='${k}';V.bp=0;go('buyers','keep')">${l}</button>`).join("")}</div><div id="bl"></div>`};
AF.buyers=()=>drawB();
const bCard=u=>{const os=bOrders(u),ad=bAddrs(u);return`<div class="pn bc"><div style="display:flex;justify-content:space-between;gap:8px;align-items:flex-start"><div style="min-width:0"><h3 style="overflow-wrap:anywhere">${esc(u.name)}</h3><div class="sm" style="overflow-wrap:anywhere">${esc(u.email)}</div></div>${bPill(u)}</div><div class="sm" style="margin:8px 0;overflow-wrap:anywhere">Mobile: ${esc(u.m||"not saved")}<br>Last login: ${u.ll?fd(u.ll):"never"}<br>Address: ${ad.length?esc(ad[0])+(ad.length>1?" (+"+(ad.length-1)+" more)":""):"not saved"}</div><div class="kp" style="grid-template-columns:1fr 1fr;margin:8px 0"><div><small>Orders</small><b>${os.length}</b></div><div><small>Spent</small><b style="font-size:20px">${money(bSpent(u))}</b></div></div><div class="btns"><button class="o s" onclick="bProf('${u.id}')">View profile</button><button class="${u.blocked?"g":"d"} s" onclick="bTog('${u.id}')">${u.blocked?"Unblock":"Block"}</button></div></div>`};
function drawB(){const el=$("bl");if(!el||!isO())return;const q=(V.bq||"").toLowerCase(),st=V.bs||"all",all=bList();
const L=all.filter(u=>(st=="all"||(st=="blk")==!!u.blocked)&&(!q||[u.name,u.email,u.m].some(x=>(x||"").toLowerCase().includes(q)))).sort((a,b)=>(a.name||"").localeCompare(b.name||"")),pgs=Math.ceil(L.length/BPG),pg=Math.min(V.bp||0,Math.max(0,pgs-1));V.bp=pg;
el.innerHTML=L.length?`<p class="sm" style="margin-bottom:8px">${L.length} buyer${L.length>1?"s":""}</p><div class="bg">${L.slice(pg*BPG,pg*BPG+BPG).map(bCard).join("")}</div>${pgs>1?`<div class="btns" style="align-items:center;margin-top:12px"><button class="o s" ${pg?"":"disabled"} onclick="V.bp--;drawB()">Previous</button><span class="sm" style="text-align:center;flex:1">Page ${pg+1} of ${pgs}</span><button class="o s" ${pg<pgs-1?"":"disabled"} onclick="V.bp++;drawB()">Next</button></div>`:""}`:`<div class="empty">${all.length?"No buyers match your search.":"No buyers have registered yet."}</div>`}
function bProf(id){if(!isO())return toast("Not allowed");const u=S.u.find(x=>x.id==id&&x.role=="buyer");if(!u)return;const os=bOrders(u),ad=bAddrs(u);
opn(`<h2>${esc(u.name)}</h2><p class="sm" style="overflow-wrap:anywhere">${esc(u.email)} · ${esc(u.m||"no mobile saved")}</p><p style="margin:8px 0">${bPill(u)} <span class="sm">${os.length} order${os.length==1?"":"s"} · ${money(bSpent(u))} spent</span></p><p class="sm">Last login: ${u.ll?fd(u.ll):"never"}</p><h3>Delivery addresses</h3>${ad.length?ad.map(a=>`<p class="sm" style="margin:4px 0">${esc(a)}</p>`).join(""):`<p class="sm">None saved.</p>`}<h3 style="margin-top:12px">Order history</h3>${os.length?os.map(o=>`<div class="ln" style="align-items:flex-start"><div class="n"><b>${o.id}</b> ${pill(o.st)}<br><span class="sm">${fd(o.cr)} · ${o.pm=="upi"?"UPI":"Cash on Delivery"}</span><br>${o.items.map(i=>esc(i.n)+" × "+i.q+" ("+money(i.pr)+")").join("<br>")}</div><b>${money(o.tot)}</b></div>`).join(""):`<p class="sm">No orders yet.</p>`}<div class="btns" style="margin-top:14px"><button class="o" onclick="cl()">Close</button><button class="${u.blocked?"g":"d"}" onclick="cl();bTog('${u.id}')">${u.blocked?"Unblock":"Block"} buyer</button></div>`)}
function bTog(id){if(!isO())return toast("Not allowed");const u=S.u.find(x=>x.id==id&&x.role=="buyer");if(!u||u.id==ME.id)return toast("Not allowed");const b=!u.blocked;
cfm(b?"Block this buyer?":"Unblock this buyer?",b?esc(u.name)+" will not be able to place new orders. Their profile and existing orders are kept.":esc(u.name)+" will be able to place orders again.",async()=>{if(!isO())return;try{await api("/buyers/"+id+"/block",{method:"POST",body:{blocked:b}});await sync();toast(b?"Buyer blocked":"Buyer unblocked");drawB()}catch(e){fail(e)}},b?"Block":"Unblock")}

/* ===== Location picker: no map, address + optional device location ===== */
function lpH(k,o){LPO[k]=o;return`<div class="lp" id="lpw_${k}">${lpIn(k)}</div>`}
const lpDraw=k=>{const e=$("lpw_"+k);if(e)e.innerHTML=lpIn(k)};
function lpKeep(k){const d=LPD[k]=LPD[k]||{};if($("lp_"+k+"_a"))d.v={a:$("lp_"+k+"_a").value,c:$("lp_"+k+"_c").value,p:$("lp_"+k+"_p").value}}
function lpIn(k){const o=LPO[k],s=lpS[k],d=LPD[k]||{},er=`<div class="er" id="e_lp_${k}"></div>`,t=`<div class="sm">${o.title}${o.req?" (required)":""}</div>`;
if(s&&!d.open)return`<div class="lpc ok">${t}<div class="lpa">📍 ${esc(fa(s))}</div><div class="sm">${s.gps?"Selected using your current location":"Entered manually"}</div>${o.after?o.after(s):""}<div class="btns"><button class="o s" onclick="lpOpen('${k}')">Change location</button></div>${er}</div>`;
const sv=!d.open&&o.saved?o.saved():[];
return`<div class="lpc">${t}${d.open?"":`<button class="b" style="width:100%;margin-top:6px" onclick="lpOpen('${k}',${o.auto?1:0})">📍 ${o.btn}</button>`}${sv.length?`<div class="sm" style="margin-top:8px">Or choose a saved address:</div><div class="lpv">${sv.map((x,i)=>`<button onclick="lpUse('${k}',${i})">${esc(fa(x))}</button>`).join("")}</div>`:""}${d.open?`<div class="btns lpb"><button class="b" onclick="lpGps('${k}')">📍 ${o.use}</button><button class="o" onclick="lpMan('${k}')">✎ ${o.man}</button></div>${d.msg?`<div class="note" style="margin-top:8px">${esc(d.msg)}</div>`:""}${d.show?`<div style="margin-top:10px">${fld("lp_"+k+"_a","Address (house / street / landmark)",{ta:1,v:(d.v||{}).a})}${fld("lp_"+k+"_c","City / town",{v:(d.v||{}).c})}${fld("lp_"+k+"_p","PIN code",{v:(d.v||{}).p,im:"numeric"})}<button class="g" style="width:100%" onclick="lpOk('${k}')">Confirm Selected Location</button></div>`:""}`:""}${er}</div>`}
function lpOpen(k,auto){const s=lpS[k];LPD[k]={open:1,show:!!s,v:s?{a:s.a,c:s.c,p:s.p}:{a:"",c:"",p:""},gps:0};lpDraw(k);if(auto)lpGps(k)}
function lpMan(k){lpKeep(k);const d=LPD[k];d.open=1;d.show=1;d.gps=0;d.lat=d.lng=null;d.msg="";lpDraw(k)}
function lpGps(k){lpKeep(k);const d=LPD[k]=LPD[k]||{open:1,v:{a:"",c:"",p:""}};d.open=1;if(!navigator.geolocation){d.show=1;d.gps=0;d.msg="Location is not available on this device or browser. Please enter the address manually. Distance will be estimated from the PIN code.";return lpDraw(k)}
d.msg="Requesting your location… please allow access when your browser asks.";lpDraw(k);
navigator.geolocation.getCurrentPosition(p=>{lpKeep(k);const x=LPD[k];if(!x)return;x.lat=p.coords.latitude;x.lng=p.coords.longitude;x.gps=1;x.show=1;x.msg="Location detected. Please check and confirm the address details below.";lpDraw(k)},e=>{lpKeep(k);const x=LPD[k];if(!x)return;x.gps=0;x.lat=x.lng=null;x.show=1;x.msg=(e&&e.code==1?"Location permission was denied. ":"Your location could not be detected. ")+"Please enter the address manually. Distance will be estimated from the PIN code.";lpDraw(k)},{timeout:10000,maximumAge:60000})}
function lpOk(k){const d=LPD[k]||{};if(!$("lp_"+k+"_a"))return;const v=chk([["lp_"+k+"_a",x=>x.length>=8?"":"Enter the full address (8+ characters)"],["lp_"+k+"_c",rq],["lp_"+k+"_p",x=>/^\d{6}$/.test(x)?"":"Enter a 6-digit PIN code"]]);if(!v)return;lpS[k]={a:v["lp_"+k+"_a"],c:v["lp_"+k+"_c"],p:v["lp_"+k+"_p"],lat:d.gps?d.lat:null,lng:d.gps?d.lng:null,gps:d.gps?1:0};LPD[k]={};lpDraw(k);const o=LPO[k];if(o&&o.onSet)o.onSet(lpS[k])}
function lpUse(k,i){const x=LPO[k].saved()[i];if(!x)return;lpS[k]={...x};LPD[k]={};lpDraw(k)}
function dnote(a){if(!CK||!a)return"";const t=tot(CK.lines,a);return t.g.map(g=>`<div class="sm" style="margin-top:6px">${esc(shopName(g.oid))}: about <b>${g.km} km</b>${g.demo?" (estimated from PIN codes)":""} · ${g.far?'<b style="color:var(--bad)">above 10 km: owner approval needed before payment</b>':g.del?"delivery "+money(g.del):"free delivery"}</div>`).join("")}
/* ===== Shop settings (owner) ===== */
async function saveLoc(s){if(!isO()||!s)return;try{await api("/store/location",{method:"PUT",body:{a:s.a,c:s.c,p:s.p,lat:s.lat,lng:s.lng,gps:!!s.gps}});await sync();toast("Shop location saved");go("settings","keep")}catch(e){fail(e)}}
VW.settings=()=>{if(!isO())return"";lpS.st=ME.loc?{...ME.loc}:null;LPD.st={};return ownBar()+`<h1>Shop Settings</h1><div class="two"><div class="pn"><h2>Shop location</h2><p class="sm" style="margin:4px 0 10px">Delivery distance is measured from this location. Deliveries above 10 km need your approval.</p>${lpH("st",{title:"Saved shop location",btn:"Choose Shop Location",req:1,use:"Use My Current Location",man:"Enter Address Manually",onSet:saveLoc})}</div><div class="pn"><h2>${esc(ME.shop)}</h2><p class="sm">${esc(ME.email)}${ME.m?" · "+esc(ME.m):""}</p><p class="sm" style="margin:8px 0">Delivery rules: within 10 km ₹49 (free for orders of ₹999+). Beyond 10 km you approve, adjust or reject each request.</p><button class="o" onclick="go('profile')">Open profile</button></div></div>`};
const ownX=()=>{const n=S.dr.filter(r=>r.oid==ME.id&&r.st=="Pending").length;return(n?`<br><b style="color:var(--bad)">${n} delivery request${n>1?"s":""} waiting for approval</b> · <a href="#" onclick="event.preventDefault();go('req')">Review</a>`:"")+`<br>📍 ${ME.loc?esc(fa(ME.loc)):"Shop location not set"} · <a href="#" onclick="event.preventDefault();go('settings')">Shop Settings</a>`};
function reqN(){const n=ME&&ME.role=="owner"?S.dr.filter(r=>r.oid==ME.id&&r.st=="Pending").length:0;document.querySelectorAll(".rqb").forEach(b=>{b.textContent=n;b.style.display=n?"grid":"none"})}
/* ===== Long-distance delivery requests (above 10 km) ===== */
function drCard(g){const r=g.dr,hd=`<div class="pn" style="margin-bottom:10px"><b>${esc(shopName(g.oid))}</b><br><span class="sm">About ${g.km} km from the shop${g.demo?" (estimated from PIN codes)":""} · items ${money(g.sub)}</span>`;
if(!r)return hd+`<p class="sm" style="margin:6px 0 8px">Send a delivery request to the shop owner. Payment opens only after they approve.</p><button class="b" style="width:100%" onclick="sendDr('${g.oid}')">Send Delivery Request to Owner</button></div>`;
if(r.st=="Pending")return hd+`<p style="margin:6px 0"><span class="pill">Waiting for owner approval</span></p><p class="sm" style="margin-bottom:8px">Request ${r.id} sent ${fd(r.cr)}. You will be notified when the owner replies. Payment options unlock after approval.</p><button class="o s" onclick="go('co','keep')">Refresh status</button></div>`;
if(r.st=="Rejected")return hd+`<p style="margin:6px 0"><span class="pill x">Rejected by owner</span></p><p class="sm" style="margin-bottom:8px">${esc(r.note||"The owner cannot deliver to this address.")}</p><button class="b s" onclick="sendDr('${g.oid}')">Send request again</button> <button class="o s" onclick="CK.step=1;go('co')">Change address</button></div>`;
return hd+`<p style="margin:6px 0"><span class="pill ok">Approved</span> Final delivery charge: <b>${money(r.chg)}</b></p></div>`}
function coR(){const t=tot(CK.lines,CK.addr),far=t.g.filter(x=>x.far);return`<h1>Owner approval needed</h1><div class="two">${sumH()}<div class="pn"><h2>Delivery above 10 km</h2><p class="sm" style="margin:4px 0 10px">Your address is more than 10 km from ${far.length>1?"these shops":"this shop"}. The shop owner must approve before you can choose COD or Pay Now.</p>${far.map(drCard).join("")}<button class="b" style="width:100%" ${t.need?"disabled":""} onclick="CK.step=2;go('co')">${t.need?"Waiting for owner approval":"Continue to payment"}</button><button class="o" style="width:100%;margin-top:8px" onclick="CK.step=1;go('co')">Change address</button></div></div>`}
async function sendDr(oid){if(!ME||ME.role!="buyer"||!CK)return;if(ME.blocked)return toast(BLK_MSG);const g=tot(CK.lines,CK.addr).g.find(x=>x.oid==oid);if(!g||!g.far)return;if(g.dr&&g.dr.st!="Rejected")return toast("Request already sent");
try{await api("/delivery-requests",{method:"POST",body:{lines:CK.lines,addr:CK.addr,cart:!!CK.cart}});await sync();bell();toast("Request sent to the shop owner");go("co","keep")}catch(e){fail(e)}}
const rqCard=r=>`<div class="pn"><div style="display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap"><b>${r.id}</b><span class="pill">Pending</span></div><p class="sm">Requested ${fd(r.cr)} by <b>${esc(r.bn||"Buyer")}</b>${r.bm?" · "+esc(r.bm):""}</p><p style="margin:6px 0">📍 ${esc(fa(r.addr))}</p><p class="sm">Distance about <b>${r.km} km</b>${r.dm?" (estimated from PIN codes)":""}. Standard delivery pricing covers only up to 10 km.</p><div style="margin:6px 0">${r.items.map(i=>`<div class="sm">${esc(i.n)} × ${i.q} · ${money(i.pr*i.q)}</div>`).join("")}<b>Items subtotal ${money(r.sub)}</b></div>${fld("dc_"+r.id,"Delivery charge to approve (₹) – adjust if needed",{v:r.sg,im:"numeric"})}<div class="btns"><button class="d" onclick="drRej('${r.id}')">Reject</button><button class="g" onclick="drAct('${r.id}')">Approve</button></div></div>`;
const rqHist=r=>`<div class="pn"><b>${r.id}</b> ${r.st=="Approved"||r.st=="Used"?'<span class="pill ok">'+(r.st=="Used"?"Approved · order placed":"Approved")+"</span>":'<span class="pill x">Rejected</span>'}<br><span class="sm">${esc(r.bn||"Buyer")} · about ${r.km} km · ${fd(r.at||r.cr)}</span><br><span class="sm">${r.items.map(i=>esc(i.n)+" × "+i.q).join(", ")}</span>${r.chg!=null?`<br>Delivery charge approved: <b>${money(r.chg)}</b>${r.chg!=r.sg?' <span class="sm">(adjusted from '+money(r.sg)+")</span>":""}${r.ord?' <span class="sm">· order '+r.ord+"</span>":""}`:r.note?`<br><span class="sm">Reason: ${esc(r.note)}</span>`:""}</div>`;
VW.req=()=>{if(!isO())return"";const L=S.dr.filter(r=>r.oid==ME.id),P=L.filter(r=>r.st=="Pending"),H=L.filter(r=>r.st!="Pending");return ownBar()+`<h1>Delivery Requests</h1><p class="sm" style="margin-bottom:10px">Buyers more than 10 km away cannot pay until you approve. You can approve, change the delivery charge, or reject.</p>${P.map(rqCard).join("")||'<div class="pn empty">No pending requests.</div>'}<h2 style="margin:14px 0 8px">History</h2>${H.map(rqHist).join("")||'<div class="pn empty">No past requests.</div>'}`};
async function drAct(id){const r=S.dr.find(x=>x.id==id);if(!isO()||!r||r.oid!=ME.id||r.st!="Pending")return toast("Not allowed");const el=$("dc_"+id),c=(el.value||"").trim();if(!/^\d+(\.\d+)?$/.test(c)){$("e_dc_"+id).textContent="Enter a delivery charge (0 or more)";el.classList.add("bad");return}
try{await api("/delivery-requests/"+id+"/approve",{method:"POST",body:{charge:Math.round(+c)}});await sync();bell();toast("Request approved");go("req")}catch(e){fail(e)}}
function drRej(id){opn(`<h2>Reject request?</h2><p class="sm" style="margin:8px 0">The buyer is told this delivery is not possible.</p>${fld("rj_r","Reason (optional)",{ta:1,opt:1})}<div class="btns"><button class="o" onclick="cl()">Cancel</button><button class="d" onclick="drNo('${id}')">Reject</button></div>`)}
async function drNo(id){const r=S.dr.find(x=>x.id==id);if(!isO()||!r||r.oid!=ME.id||r.st!="Pending")return toast("Not allowed");const note=($("rj_r").value||"").trim();cl();try{await api("/delivery-requests/"+id+"/reject",{method:"POST",body:{note}});await sync();bell();toast("Request rejected");go("req")}catch(e){fail(e)}}
function drBuyer(){const L=S.dr.filter(r=>r.bid==ME.id&&r.st!="Used").slice(0,6);if(!L.length)return"";return`<div class="pn"><h2>Delivery requests (above 10 km)</h2>${L.map(r=>`<div class="ln" style="align-items:flex-start"><div class="n"><b>${r.id}</b> · ${esc(r.shop)} ${r.st=="Approved"?'<span class="pill ok">Approved</span>':r.st=="Rejected"?'<span class="pill x">Rejected</span>':'<span class="pill">Waiting for owner</span>'}<br><span class="sm">${r.items.map(i=>esc(i.n)+" × "+i.q).join(", ")} · about ${r.km} km${r.dm?" (estimated)":""}</span>${r.st=="Approved"?`<br>Owner-approved delivery charge: <b>${money(r.chg)}</b><br>Grand total: <b>${money(r.sub+r.chg)}</b>`:r.st=="Rejected"?`<br><span class="sm">${esc(r.note||"The owner could not deliver to this address.")}</span>`:""}</div>${r.st=="Approved"?`<button class="b s" onclick="resumeDr('${r.id}')">Continue to Checkout</button>`:""}</div>`).join("")}</div>`}
function drBan(){if(!ME||ME.role!="buyer")return"";const a=S.dr.filter(r=>r.bid==ME.id&&r.st=="Approved").length,p=S.dr.filter(r=>r.bid==ME.id&&r.st=="Pending").length;return(a?`<div class="note">✅ ${a} delivery request${a>1?"s":""} approved by the shop owner. <button class="b s" onclick="go('orders')">View &amp; checkout</button></div>`:"")+(p?`<div class="note">⏳ ${p} delivery request${p>1?"s":""} waiting for owner approval. <button class="o s" onclick="go('orders')">View status</button></div>`:"")}
function resumeDr(id){const r=S.dr.find(x=>x.id==id&&x.bid==ME.id);if(!r||r.st!="Approved")return toast("This request is not available");if(ME.blocked)return toast(BLK_MSG);const L={};for(const it of r.items){const p=PD(it.id);if(!p||!live(p)||p.st<it.q||!storeOk(p.oid))return toast((p?p.n:"An item")+" is no longer available");L[it.id]=it.q}CK={lines:L,addr:{...r.addr},step:2,cart:r.cart};go("co")}
/* Other users' changes (new orders, approvals...) appear without a manual refresh */
let POLLING=0;
async function poll(){if(!ME||POLLING||document.hidden||$("ovl").classList.contains("on"))return;POLLING=1;
try{const sg=()=>JSON.stringify([S.o.map(o=>o.id+o.st+o.pay),S.dr.map(r=>r.id+r.st),S.n.length,S.p.map(p=>p.id+":"+p.st+p.on)]);const was=sg();await sync();
if(was!=sg()){bell();const ae=document.activeElement,typing=ae&&/INPUT|TEXTAREA|SELECT/.test(ae.tagName);if(!typing&&(["req","orders","ord","today"].includes(V.v)||(V.v=="co"&&CK&&CK.step==5)))go(V.v,"keep")}}
catch(e){if(e.status==401)fail(e)}finally{POLLING=0}}
setInterval(poll,20000);addEventListener("focus",poll);
const CXR=["Ordered by mistake","Found a better price elsewhere","Want to change the items or address","Delivery is taking too long","Payment problem","Other"];
function cancelAsk(id){const o=S.o.find(x=>x.id==id);if(!ME||ME.role!="buyer"||!o||o.by!=ME.email)return toast("Not allowed");if(!["Awaiting Payment","Confirmed"].includes(o.st))return toast("This order can no longer be cancelled");
opn(`<h2>Cancel order ${id}?</h2><p class="sm" style="margin:6px 0 12px">Please tell us why you want to cancel. The order is cancelled only after you confirm below.</p>${fld("cx_r","Reason for cancelling",{sel:["Select a reason",...CXR]})}${fld("cx_t","Details <span class=\"sm\">(required if you choose Other)</span>",{ta:1,opt:1})}<div class="btns"><button class="o" onclick="cl()">Keep order</button><button class="d" onclick="cancelGo('${id}')">Cancel Order</button></div>`)}
function cancelGo(id){const v=chk([["cx_r",x=>x=="Select a reason"?"Please choose a reason":""],["cx_t",(x,v)=>v.cx_r=="Other"&&x.length<3?"Please write the reason":""]]);if(!v)return;const r=v.cx_r=="Other"?v.cx_t:v.cx_r+(v.cx_t?" – "+v.cx_t:"");cl();cancel(id,"buyer",r)}
/* ---- restore session after refresh ---- */
(async function(){try{await sync()}catch(e){return}left=1;const i=$("intro");if(i)i.remove();document.body.classList.remove("sp");login()})();
